  `imagen_url` varchar(255) DEFAULT NULL,
  `imagen_url1` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id_ejercicio`)
) ENGINE=InnoDB AUTO_INCREMENT=2089 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
